import type { ReactNode } from "react";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";

type FieldTag = "generated" | "manual";

type FieldProps = {
  label: ReactNode;
  /** The id of the control inside; the hint and error ids derive from it. */
  htmlFor: string;
  required?: boolean;
  hint?: ReactNode;
  error?: ReactNode;
  /** Whether the value was generated by the platform or typed by the owner. */
  tag?: FieldTag;
  /** Something next to the label, e.g. a small button. */
  action?: ReactNode;
  children: ReactNode;
};

const TAGS: Record<FieldTag, { label: string; className: string }> = {
  generated: { label: "Generated", className: "bg-accent-soft text-primary" },
  manual: { label: "Manual", className: "bg-surface-2 text-fg-muted" },
};

/**
 * Description: Derive the DOM id of a field's hint text.
 * Input: The control's id.
 * Output: `<id>-hint`.
 * Use case: Field and describedBy (aria-describedby wiring).
 * Author: Mr. Sachin Sharma
 * Created: 2026-10-14
 * Last modified: 2026-10-15
 */
export function hintId(htmlFor: string): string {
  return `${htmlFor}-hint`;
}

/**
 * Description: Derive the DOM id of a field's error message.
 * Input: The control's id.
 * Output: `<id>-error`.
 * Use case: Field, describedBy and error summaries.
 * Author: Mr. Sachin Sharma
 * Created: 2026-10-14
 * Last modified: 2026-10-15
 */
export function errorId(htmlFor: string): string {
  return `${htmlFor}-error`;
}

/**
 * Description: Build the ARIA attributes a control inside a Field needs.
 * Input: The control's id and whether it has a hint and/or an error.
 * Output: aria-describedby (hint and error ids) and aria-invalid, so the hint and
 *   error are read out with the control. Spread them onto the input.
 * Use case: Every input of the tenant forms.
 * Author: Mr. Sachin Sharma
 * Created: 2026-10-14
 * Last modified: 2026-10-15
 */
export function describedBy(
  htmlFor: string,
  { hint, error }: { hint?: unknown; error?: unknown },
): {
  "aria-describedby": string | undefined;
  "aria-invalid": true | undefined;
} {
  const ids = [
    hint ? hintId(htmlFor) : null,
    error ? errorId(htmlFor) : null,
  ].filter((id): id is string => id !== null);
  return {
    "aria-describedby": ids.length > 0 ? ids.join(" ") : undefined,
    "aria-invalid": error ? true : undefined,
  };
}

/**
 * Description: Render a labelled form control with its tag, hint and error.
 * Input: The label, the control id, required flag, hint, error, tag, a header
 *   action and the control itself.
 * Output: The label (red asterisk + "(required)" for screen readers when required),
 *   the control, the hint, and the error directly below the control.
 * Use case: Every field of the tenant forms (CLAUDE.md: errors under their field).
 * Author: Mr. Sachin Sharma
 * Created: 2026-10-14
 * Last modified: 2026-10-15
 */
export function Field({
  label,
  htmlFor,
  required,
  hint,
  error,
  tag,
  action,
  children,
}: FieldProps) {
  return (
    <div className="flex min-w-0 flex-col gap-1.5">
      <div className="flex min-h-5 items-center justify-between gap-3">
        <div className="flex min-w-0 items-center gap-2">
          <Label htmlFor={htmlFor} className="text-sm font-medium text-fg">
            {label}
            {required ? (
              <>
                {/* The asterisk is for the eye; screen readers hear the word. */}
                <span aria-hidden="true" className="ml-0.5 text-destructive">
                  *
                </span>
                <span className="sr-only"> (required)</span>
              </>
            ) : null}
          </Label>
          {tag ? (
            <Badge variant="secondary" className={TAGS[tag].className}>
              {TAGS[tag].label}
            </Badge>
          ) : null}
        </div>
        {action ? <div className="shrink-0">{action}</div> : null}
      </div>
      {children}
      {hint ? (
        <p id={hintId(htmlFor)} className="text-xs text-fg-subtle">
          {hint}
        </p>
      ) : null}
      {error ? (
        <p id={errorId(htmlFor)} className="text-sm text-destructive">
          {error}
        </p>
      ) : null}
    </div>
  );
}
